SCHEMA = """
CREATE TABLE IF NOT EXISTS nodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    node_type TEXT NOT NULL,
    description TEXT,
    parent_id INTEGER REFERENCES nodes(id),
    aliases TEXT, causes TEXT, symptoms TEXT, treatments TEXT,
    affected_worldwide INTEGER DEFAULT 0, prevalence_text TEXT,
    mortality_rate REAL DEFAULT 0.0, is_rare INTEGER DEFAULT 0,
    onset TEXT DEFAULT 'chronic', sources TEXT, research_links TEXT
);
CREATE VIRTUAL TABLE IF NOT EXISTS nodes_fts USING fts5(
    name, description, aliases, causes, symptoms, treatments,
    content='nodes', content_rowid='id'
);
"""

def create_db(conn):
    conn.executescript(SCHEMA)

def insert_node(conn, node, id_map):
    parent_id = id_map.get(node.get('parent_code'))
    cursor = conn.execute(
        """INSERT INTO nodes
           (code, name, node_type, description, parent_id,
            aliases, causes, symptoms, treatments,
            affected_worldwide, prevalence_text, mortality_rate,
            is_rare, onset, sources, research_links)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (node['code'], node['name'], node['node_type'],
         node.get('description',''), parent_id,
         node.get('aliases',''), node.get('causes',''),
         node.get('symptoms',''), node.get('treatments',''),
         node.get('affected_worldwide',0), node.get('prevalence_text',''),
         node.get('mortality_rate',0.0), node.get('is_rare',0),
         node.get('onset','chronic'), node.get('sources',''),
         node.get('research_links','')))
    id_map[node['code']] = cursor.lastrowid

def main():
    if os.path.exists(DB_PATH):
        os.remove(DB_PATH)
    conn = sqlite3.connect(DB_PATH)
    create_db(conn)
    id_map = {}
    ordered = ([n for n in DATA if n['node_type']=='chapter'] +
               [n for n in DATA if n['node_type']=='block'] +
               [n for n in DATA if n['node_type']=='disease'])
    for node in ordered:
        insert_node(conn, node, id_map)
    conn.commit()
    conn.close()
    chapters = sum(1 for n in DATA if n['node_type']=='chapter')
    diseases = sum(1 for n in DATA if n['node_type']=='disease')
    print(f"Seeded {chapters} chapters and {diseases} diseases into {DB_PATH}")

if __name__ == "__main__":
    main()
